import React, { useContext, useEffect, useState } from "react";
import { SocketContext } from "../context/socket";
import { Table } from 'antd';
import NavMenu from "./SharedComponents/navMenu";
import '../styles/record.css';

const ManageRecords = () => {
    const socket = useContext(SocketContext);
    const [workspaces, setWorkspaces] = useState([]);

    useEffect(() => {
        fetch('/api/workspaces')
            .then(response => response.json())
            .then(data => setWorkspaces(data));

        const handleNewWorkspace = newWorkspace => {
            setWorkspaces(prev => [...prev, newWorkspace]);
        };

        socket.on('workspaceAdded', handleNewWorkspace);

        return () => {
            socket.off('workspaceAdded', handleNewWorkspace);
        };
    }, [socket]);

    const columns = [
        { title: 'Name', dataIndex: 'name', key: 'name' },
        { title: 'Location', dataIndex: 'location', key: 'location' },
        { title: 'Status', dataIndex: 'status', key: 'status' }
    ];

    return (
        <div className="view-workspaces">
            <NavMenu isAdmin={false} breadcrum="View Workspaces" pagePath="/view-workspaces" />
            <Table columns={columns} dataSource={workspaces} rowKey="id" />
        </div>
    );
};

export default ManageRecords;




